// Package gomast is the Gom abstract-syntax-tree package generated by
// tomgo itself from the five .gom files in src/tom/gom/adt/:
//
//	Code.gom  Gom.gom  Objects.gom  Rule.gom  SymbolTable.gom
//
// This is the "self-bootstrap" step (Phase 3 of the porting plan): the
// hand-written Go structs that previously lived in internal/gom/ast.go
// are replaced by the Gom-generated types, so that tomgo manipulates
// exactly the same abstract structures the reference Java Gom does.
//
// Every term lives in the shared-objects factory of this package; two
// structurally equal terms compare equal by pointer.
//
// # Regeneration
//
// From the tomgo/ directory:
//
//	rm -rf internal/gomast/*.go
//	go run ./cmd/tomgo gom-batch --pkg gomast -o internal/gomast \
//	    ../src/tom/gom/adt/Code.gom \
//	    ../src/tom/gom/adt/Gom.gom \
//	    ../src/tom/gom/adt/Objects.gom \
//	    ../src/tom/gom/adt/Rule.gom \
//	    ../src/tom/gom/adt/SymbolTable.gom
//	rm internal/gomast/go.mod   # gomast lives inside the tomgo module
//	# (re-create this doc.go file if it was wiped)
//	go test ./...
//
// The generated sources should NEVER be edited by hand — every change
// must go through the .gom sources and a clean regeneration.
package gomast
